window.AJSportProfiles = {"general":[{"claim":"Across randomised trials, strength training cut sports injuries to under a third (RR 0.32) and nearly halved overuse injuries; it was far more protective than stretching.","source":"Lauersen, Bertelsen & Andersen 2014, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/48/11/871"},{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"},{"claim":"In professional footballers, one strength session a week in season maintained pre-season gains in strength and sprint speed, whereas one session every two weeks let them decline.","source":"Rønnestad, Nymark & Raastad 2011, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/21873897/"},{"claim":"Doing endurance and strength training together does not blunt muscle growth or maximal strength, but can blunt explosive strength, especially when both are done in the same session.","source":"Schumann et al. 2022, Sports Medicine","url":"https://researchonline.jcu.edu.au/71546/"},{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"},{"claim":"A Copenhagen adductor strengthening programme lowered the odds of groin problems by 41% in male football players.","source":"Harøy et al. 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/3/150"},{"claim":"The FIFA 11+ warm-up (running, strength, balance and plyometric work) reduced overall football injuries by 39%.","source":"Thorborg et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/7/562"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"},{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"},{"claim":"Strength training (resistance plus plyometrics, 2-3 times a week for 8-12 weeks) produced a large improvement in running economy in highly trained distance runners.","source":"Balsalobre-Fernández, Santos-Concejero & Grivas 2016, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/26694507/"},{"claim":"Adding heavy strength training to endurance training improves running and cycling economy and performance, with heavy strength work giving the clearest benefit for cyclists.","source":"Rønnestad & Mujika 2014, Scandinavian Journal of Medicine & Science in Sports","url":"https://doi.org/10.1111/sms.12104"},{"claim":"Gains in lower-body (squat) strength transfer to sprint performance, with strength gains strongly correlated with sprint improvements.","source":"Seitz et al. 2014, Sports Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/25059334/"}],"sports":[{"id":"tennis","name":"Tennis","aliases":["lawn tennis"],"group":"Racket","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","ankle","wrist","calf"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated short explosive rallies of a few seconds with brief recovery between points, over matches that can last hours.","summary":"Tennis is short explosive rallies with lots of rotation and overhead hitting. The plan builds leg and rotational power, which a junior tennis study showed can raise serve speed, and adds rotator cuff work, which has cut shoulder problems in overhead athletes.","evidence":[{"claim":"A 6-week conditioning programme significantly increased serve velocity in junior tennis players, with no change in a control group.","source":"Fernandez-Fernandez et al. 2013, Journal of Sports Science and Medicine","url":"https://www.jssm.org/jssm-12-232.xml-abst"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"moderate"},{"id":"padel","name":"Padel","aliases":["paddle tennis"],"group":"Racket","q":{"maxStrength":2,"power":2,"rotational":3,"unilateral":3,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":2,"mass":1},"prehab":["shoulderER","ankle","calf","wrist"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Short repeated rallies with quick lateral moves and lots of overhead and wall play.","summary":"Padel combines quick lateral footwork with overhead smashes and rotational shots. The plan builds leg strength and rotational power and adds shoulder and ankle work, borrowed from tennis and court-sport research because padel-specific studies are scarce.","evidence":[],"confidence":"limited"},{"id":"squash","name":"Squash","aliases":["squash rackets"],"group":"Racket","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":2,"neck":0,"trunk":2,"mass":1},"prehab":["ankle","landing","calf","wrist"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"High-intensity rallies with repeated lunges and sharp changes of direction, demanding both aerobic fitness and repeated sprint ability.","summary":"Squash is relentless lunging and turning in a small court. The plan builds single-leg strength and power for lunging and adds balance and landing work, which reduce ankle and knee injuries in court sports.","evidence":[{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"}],"confidence":"limited"},{"id":"badminton","name":"Badminton","aliases":[],"group":"Racket","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":3,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["ankle","landing","calf","shoulderER"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Very short, explosive rallies with jumps, lunges and fast recovery between points.","summary":"Badminton is explosive jumping, lunging and overhead hitting. The plan builds leg power and single-leg strength and adds landing, ankle and rotator cuff work, which have been shown to reduce knee, ankle and shoulder problems in jumping and overhead sports.","evidence":[{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"limited"},{"id":"tabletennis","name":"Table tennis","aliases":["ping pong"],"group":"Racket","q":{"maxStrength":1,"power":2,"rotational":3,"unilateral":2,"upperPull":1,"upperPush":1,"lowerBody":2,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["shoulderER","lowback","wrist"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":null,"energy":"Very short rallies with rapid footwork and repeated fast rotation of the trunk.","summary":"Table tennis needs quick feet and fast trunk rotation rather than raw strength. The plan uses moderate strength work with rotational power and shoulder and back resilience work; sport-specific strength research is limited.","evidence":[],"confidence":"limited"},{"id":"pickleball","name":"Pickleball","aliases":[],"group":"Racket","q":{"maxStrength":1,"power":1,"rotational":2,"unilateral":2,"upperPull":1,"upperPush":1,"lowerBody":2,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["ankle","calf","shoulderER","wrist"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":"lower","energy":"Short rallies with lots of quick small steps and reactive movement at the net.","summary":"Pickleball is short reactive rallies with lots of quick lateral steps. The plan focuses on general leg strength, balance and calf strength to protect ankles and Achilles, plus shoulder care, drawing on general injury-prevention research as pickleball studies are scarce.","evidence":[{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"}],"confidence":"limited"},{"id":"football","name":"Football (soccer)","aliases":["soccer","futsal","five-a-side"],"group":"Team field","q":{"maxStrength":3,"power":3,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":1,"trunk":2,"mass":1},"prehab":["nordic","copenhagen","landing","ankle","calf"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Intermittent running with repeated sprints, jumps and changes of direction over 90 minutes, on a strong aerobic base.","summary":"Football is repeated sprints, cuts and kicks over 90 minutes. The plan builds leg strength and speed and includes Nordic hamstring, Copenhagen adductor and landing work, which have each been shown to cut hamstring, groin and knee injuries in footballers.","evidence":[{"claim":"The FIFA 11+ warm-up (running, strength, balance and plyometric work) reduced overall football injuries by 39%.","source":"Thorborg et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/7/562"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"},{"claim":"A Copenhagen adductor strengthening programme lowered the odds of groin problems by 41% in male football players.","source":"Harøy et al. 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/3/150"},{"claim":"In professional footballers, one strength session a week in season maintained pre-season gains in strength and sprint speed, whereas one session every two weeks let them decline.","source":"Rønnestad, Nymark & Raastad 2011, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/21873897/"}],"confidence":"strong"},{"id":"rugbyunion","name":"Rugby union","aliases":["rugby","rugby sevens","sevens"],"group":"Team field","q":{"maxStrength":3,"power":3,"rotational":2,"unilateral":2,"upperPull":3,"upperPush":3,"lowerBody":3,"grip":2,"neck":3,"trunk":3,"mass":2},"prehab":["neck","nordic","landing","shoulderER"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Repeated high-intensity efforts of sprinting, tackling and rucking with short recoveries, on top of heavy contact.","summary":"Rugby demands strength, power and the ability to absorb repeated collisions. The plan prioritises heavy lifting and power, with neck strengthening and movement control work, which a large schools trial linked to fewer concussions and injuries.","evidence":[{"claim":"A pre-activity movement control warm-up (Activate) in schoolboy rugby was associated with fewer concussions, and teams doing it three or more times a week had 72% fewer match injuries.","source":"Hislop et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/15/1140"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"rugbyleague","name":"Rugby league","aliases":["league"],"group":"Team field","q":{"maxStrength":3,"power":3,"rotational":2,"unilateral":2,"upperPull":3,"upperPush":3,"lowerBody":3,"grip":2,"neck":3,"trunk":3,"mass":2},"prehab":["neck","nordic","landing","shoulderER"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Repeated sprints and tackles with short recoveries, with more running and tackling per player than union.","summary":"Rugby league is repeated tackling and sprinting with little rest. The plan builds heavy strength and power and adds neck and hamstring work, drawing on rugby union and contact-sport research showing these reduce concussion and hamstring injury.","evidence":[{"claim":"A pre-activity movement control warm-up (Activate) in schoolboy rugby was associated with fewer concussions, and teams doing it three or more times a week had 72% fewer match injuries.","source":"Hislop et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/15/1140"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"americanfootball","name":"American football","aliases":["gridiron","nfl"],"group":"Team field","q":{"maxStrength":3,"power":3,"rotational":2,"unilateral":2,"upperPull":2,"upperPush":3,"lowerBody":3,"grip":2,"neck":3,"trunk":3,"mass":2},"prehab":["neck","nordic","landing","shoulderER"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Very short, maximal plays of a few seconds followed by long rests between downs.","summary":"American football is short, maximal bursts of collision and sprinting. The plan focuses on maximal strength and power and adds neck strengthening, since stronger necks are linked to fewer concussions, plus hamstring and landing work.","evidence":[{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"},{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"aussierules","name":"Australian rules football","aliases":["afl","aussie rules","footy"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":1,"neck":2,"trunk":3,"mass":1},"prehab":["nordic","copenhagen","landing","ankle","neck"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"High running volumes with repeated sprints, jumps and contests over long matches.","summary":"Aussie rules combines long running distances with sprints, marking jumps and tackles. The plan builds leg strength and power with a strong emphasis on Nordic hamstring work, because AFL players with weak eccentric hamstrings are several times more likely to strain them.","evidence":[{"claim":"Australian footballers with low eccentric hamstring strength in preseason had a 2.7 to 4.3 times higher risk of hamstring strain.","source":"Opar et al. 2015, Medicine & Science in Sports & Exercise","url":"https://pubmed.ncbi.nlm.nih.gov/25137368/"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"gaelicfootball","name":"Gaelic football","aliases":["gaa","ladies gaelic football"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":1,"neck":1,"trunk":2,"mass":1},"prehab":["nordic","landing","ankle","copenhagen"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Intermittent running with repeated sprints, jumps and physical contests.","summary":"Gaelic football is repeated sprints, catches and turns. The plan builds leg strength and power and includes landing and balance work like the GAA 15 warm-up, which improved landing technique in Gaelic players, plus Nordic hamstring work.","evidence":[{"claim":"The GAA 15 neuromuscular warm-up improved balance and landing technique (ACL risk markers) in Gaelic football and hurling players.","source":"O'Malley et al. 2017, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/27398918/"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"hurling","name":"Hurling","aliases":["camogie"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":1,"trunk":3,"mass":1},"prehab":["nordic","landing","ankle","shoulderER","wrist"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Intermittent sprints and contests with powerful rotational striking.","summary":"Hurling mixes sprinting with fast rotational striking and contact. The plan builds leg and rotational power, adds grip strength and includes landing, balance and hamstring work shown to reduce lower-limb injury risk in Gaelic games and field sports.","evidence":[{"claim":"The GAA 15 neuromuscular warm-up improved balance and landing technique (ACL risk markers) in Gaelic football and hurling players.","source":"O'Malley et al. 2017, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/27398918/"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"fieldhockey","name":"Field hockey","aliases":["hockey"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["nordic","copenhagen","lowback","ankle","landing"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated sprints in a crouched posture with quick changes of direction.","summary":"Hockey is repeated sprinting while bent over a stick. The plan builds leg strength and power, trunk and back endurance for the crouched posture, and hamstring and groin work borrowed from football research, as hockey-specific trials are limited.","evidence":[{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"},{"claim":"A Copenhagen adductor strengthening programme lowered the odds of groin problems by 41% in male football players.","source":"Harøy et al. 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/3/150"}],"confidence":"limited"},{"id":"lacrosse","name":"Lacrosse","aliases":[],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":2,"trunk":3,"mass":1},"prehab":["landing","nordic","ankle","shoulderER","neck"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Intermittent sprinting, cutting and shooting with some body contact.","summary":"Lacrosse involves sprinting, sharp cuts and rotational shooting. The plan builds leg and rotational power and adds landing and cutting work, which cuts ACL injury risk by about half in field and court sports.","evidence":[{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"}],"confidence":"limited"},{"id":"ultimate","name":"Ultimate frisbee","aliases":["ultimate","frisbee"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["landing","ankle","nordic","calf"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated sprints, cuts and jumps with short recoveries between points.","summary":"Ultimate is repeated sprints, cuts and jumps to catch. The plan builds leg strength and power and adds landing, balance and hamstring work, which reduce knee, ankle and hamstring injuries in similar running sports.","evidence":[{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"limited"},{"id":"cricket","name":"Cricket","aliases":[],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","lowback","nordic","ankle"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":null,"energy":"Mostly low-intensity play punctuated by short explosive efforts: bowling run-ups, sprints between wickets and throws.","summary":"Cricket needs explosive, rotational power for bowling, batting and throwing. The plan builds leg and rotational power with back and shoulder resilience work, based on general throwing and injury-prevention research because cricket-specific strength trials are limited.","evidence":[{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"limited"},{"id":"baseball","name":"Baseball / softball","aliases":["softball","rounders"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":2,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","wrist","nordic"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"upper","energy":"Brief maximal efforts (throwing, swinging, sprinting) separated by long rests.","summary":"Baseball and softball are short, explosive throws, swings and sprints. The plan builds rotational and leg power and adds shoulder and forearm care, as prevention programmes have been shown to reduce shoulder and elbow throwing injuries.","evidence":[{"claim":"A warm-up programme of stretching, mobility and balance exercises reduced shoulder and elbow throwing injuries in youth baseball players.","source":"Sakata et al. 2019, American Journal of Sports Medicine","url":"https://doi.org/10.1177/0363546519861378"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"moderate"},{"id":"basketball","name":"Basketball","aliases":[],"group":"Team court","q":{"maxStrength":2,"power":3,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["landing","ankle","calf","hipAbd"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated sprints, jumps and changes of direction with short recoveries.","summary":"Basketball is constant jumping, landing and cutting. The plan builds leg strength and jump power and adds landing and balance work, which have been shown to cut ACL injuries and ankle sprains.","evidence":[{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"},{"claim":"A balance training programme reduced ankle sprains in high school basketball and football (soccer) players (1.13 vs 1.87 per 1,000 exposures).","source":"McGuine & Keene 2006, American Journal of Sports Medicine","url":"https://www.aafp.org/pubs/afp/issues/2006/1115/p1777.html"}],"confidence":"strong"},{"id":"netball","name":"Netball","aliases":[],"group":"Team court","q":{"maxStrength":2,"power":3,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["landing","ankle","calf","hipAbd"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Short repeated sprints, jumps and sudden stops, with frequent single-leg landings.","summary":"Netball is full of sudden stops and single-leg landings. The plan builds leg strength and power and puts landing and balance work at the centre, because neuromuscular training cuts non-contact ACL injuries in female athletes by around two thirds.","evidence":[{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"},{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"}],"confidence":"moderate"},{"id":"volleyball","name":"Volleyball","aliases":["beach volleyball"],"group":"Team court","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":2,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["landing","ankle","shoulderER","calf"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Short explosive rallies with repeated maximal jumps and long breaks between points.","summary":"Volleyball is repeated maximal jumping and overhead hitting. The plan builds jump power and adds balance, landing and rotator cuff work, which have been shown to reduce ankle sprains in volleyball and shoulder problems in overhead athletes.","evidence":[{"claim":"Balance board training reduced ankle sprains in volleyball players, mainly in those with a previous sprain.","source":"Verhagen et al. 2004, American Journal of Sports Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/15310562/"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"strong"},{"id":"handball","name":"Handball","aliases":["team handball"],"group":"Team court","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","landing","ankle","hipAbd"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"all","energy":"Repeated sprints, jumps and throws with contact and short recoveries.","summary":"Handball combines jumping, cutting, contact and powerful throwing. The plan builds leg and rotational power and adds a rotator cuff programme, which cut shoulder problems by 28% in elite handball players, plus landing work for the knees.","evidence":[{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"},{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"}],"confidence":"strong"},{"id":"icehockey","name":"Ice hockey","aliases":[],"group":"Team court","q":{"maxStrength":3,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":2,"trunk":3,"mass":2},"prehab":["copenhagen","hipAbd","neck","lowback"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"all","energy":"Very intense shifts of 30-60 seconds with long rests on the bench, plus body contact.","summary":"Ice hockey is short, all-out shifts with powerful skating strides and contact. The plan builds leg strength and power and includes adductor strengthening, which cut groin strains by about four-fifths in professional hockey players.","evidence":[{"claim":"A preseason adductor strengthening programme in professional ice hockey cut adductor strains from 3.2 to 0.71 per 1,000 game exposures.","source":"Tyler et al. 2002, American Journal of Sports Medicine","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4223288"},{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"}],"confidence":"moderate"},{"id":"mma","name":"MMA","aliases":["mixed martial arts","cage fighting"],"group":"Combat","q":{"maxStrength":3,"power":3,"rotational":3,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":3,"grip":3,"neck":3,"trunk":3,"mass":0},"prehab":["neck","shoulderER","lowback","fingers"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Repeated high-intensity bursts of striking and grappling over 3-5 minute rounds.","summary":"MMA needs both grappling strength and fast striking power while staying within a weight class. The plan builds strength and power relative to body weight, with neck and grip work, reflecting research that stronger, more powerful fighters perform better.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"}],"confidence":"moderate"},{"id":"boxing","name":"Boxing","aliases":[],"group":"Combat","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":2,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":1,"neck":3,"trunk":3,"mass":0},"prehab":["neck","shoulderER","wrist"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"upper","energy":"Repeated short bursts of punching and movement over 2-3 minute rounds with short rests.","summary":"Boxing relies on fast, rotational punching power and the ability to take a punch while making weight. The plan focuses on leg-to-trunk power and neck strength rather than bulk, based on combat-sport research linking power to performance level.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"}],"confidence":"moderate"},{"id":"kickboxing","name":"Kickboxing / Muay Thai","aliases":["muay thai","thai boxing","k1"],"group":"Combat","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":3,"trunk":3,"mass":0},"prehab":["neck","hipAbd","ankle","shoulderER"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"all","energy":"Repeated bursts of striking and clinching over 2-3 minute rounds.","summary":"Kickboxing and Muay Thai need explosive kicks, punches and a strong clinch. The plan builds power relative to body weight, single-leg strength for kicking and neck strength for the clinch, based on wider combat-sport research.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"}],"confidence":"limited"},{"id":"bjj","name":"Brazilian jiu-jitsu","aliases":["jiu jitsu","bjj","grappling","no-gi"],"group":"Combat","q":{"maxStrength":3,"power":2,"rotational":2,"unilateral":1,"upperPull":3,"upperPush":2,"lowerBody":3,"grip":3,"neck":3,"trunk":3,"mass":0},"prehab":["neck","lowback","fingers","shoulderER"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Long sustained grappling efforts with repeated isometric gripping and bursts of scrambling.","summary":"Jiu-jitsu is sustained grappling where strength, grip and trunk endurance decide positions. The plan builds maximal strength relative to body weight with grip, neck and back work, as grappling success is linked to high strength.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"}],"confidence":"limited"},{"id":"judo","name":"Judo","aliases":[],"group":"Combat","q":{"maxStrength":3,"power":3,"rotational":3,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":3,"grip":3,"neck":2,"trunk":3,"mass":0},"prehab":["neck","lowback","fingers","shoulderER"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Intermittent explosive throwing attempts and grip fighting over matches of about four minutes.","summary":"Judo is explosive throwing built on strong pulling and gripping. The plan builds maximal pulling strength, power and grip relative to body weight, with neck and back work, reflecting research that higher-level grapplers are stronger and more powerful.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"}],"confidence":"moderate"},{"id":"wrestling","name":"Wrestling","aliases":["freestyle wrestling","greco-roman"],"group":"Combat","q":{"maxStrength":3,"power":3,"rotational":2,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":3,"grip":3,"neck":3,"trunk":3,"mass":0},"prehab":["neck","lowback","shoulderER","fingers"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Repeated high-force grappling efforts over periods of about three minutes.","summary":"Wrestling demands high strength and power under fatigue within a weight class. The plan prioritises maximal strength relative to body weight plus neck and grip work, based on research showing successful grapplers are stronger and more powerful.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"}],"confidence":"moderate"},{"id":"karate","name":"Karate / taekwondo","aliases":["taekwondo","tkd","martial arts","kung fu"],"group":"Combat","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":1,"neck":1,"trunk":3,"mass":0},"prehab":["hipAbd","ankle","landing"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Short, very fast bursts of kicking and striking with brief pauses.","summary":"Karate and taekwondo rely on fast, explosive kicks and strikes. The plan builds single-leg strength and speed-focused power relative to body weight, as striking success is tied to fast, light-load power more than raw force.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"}],"confidence":"limited"},{"id":"cycling","name":"Road cycling","aliases":["cycling","bike","time trial","gravel"],"group":"Endurance","q":{"maxStrength":3,"power":1,"rotational":0,"unilateral":2,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":2,"mass":0},"prehab":["lowback","hipAbd"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Long aerobic efforts with surges, climbs and sprints.","summary":"Cycling is mainly aerobic, but heavy leg strength training makes riders more economical. The plan uses heavy, low-rep leg work kept separate from hard rides, plus back endurance, without adding unnecessary upper-body mass.","evidence":[{"claim":"Adding heavy strength training to endurance training improves running and cycling economy and performance, with heavy strength work giving the clearest benefit for cyclists.","source":"Rønnestad & Mujika 2014, Scandinavian Journal of Medicine & Science in Sports","url":"https://doi.org/10.1111/sms.12104"},{"claim":"Doing endurance and strength training together does not blunt muscle growth or maximal strength, but can blunt explosive strength, especially when both are done in the same session.","source":"Schumann et al. 2022, Sports Medicine","url":"https://researchonline.jcu.edu.au/71546/"}],"confidence":"strong"},{"id":"mtb","name":"Mountain biking","aliases":["mtb","downhill","enduro","cyclocross"],"group":"Endurance","q":{"maxStrength":2,"power":3,"rotational":1,"unilateral":2,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["lowback","wrist","shoulderER"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Aerobic riding with repeated short, high-power climbs and technical bursts.","summary":"Mountain biking needs leg strength and power for climbs plus upper-body and grip strength to control the bike. The plan combines heavy leg work with upper-body, grip and trunk strength, drawing on road cycling research as MTB-specific studies are limited.","evidence":[{"claim":"Adding heavy strength training to endurance training improves running and cycling economy and performance, with heavy strength work giving the clearest benefit for cyclists.","source":"Rønnestad & Mujika 2014, Scandinavian Journal of Medicine & Science in Sports","url":"https://doi.org/10.1111/sms.12104"}],"confidence":"limited"},{"id":"swimming","name":"Swimming","aliases":["open water swimming"],"group":"Endurance","q":{"maxStrength":2,"power":2,"rotational":1,"unilateral":1,"upperPull":3,"upperPush":2,"lowerBody":2,"grip":0,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","lowback"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"upper","energy":"From short sprint races to long aerobic sets, with high shoulder training volume.","summary":"Swimming relies on upper-body pulling power and a strong trunk, with high shoulder loads. The plan uses low-volume, high-force or fast strength work, which transfers best to swim performance, plus rotator cuff work to protect the shoulders.","evidence":[{"claim":"Low-volume, high-velocity or high-force resistance training transfers best to swimming performance and stroke length.","source":"Crowley, Harrison & Lyons 2017, Sports Medicine","url":"https://pure.ul.ie/en/publications/the-impact-of-resistance-training-on-swimming-performance-a-syste/"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"moderate"},{"id":"rowing","name":"Rowing","aliases":["indoor rowing","erg","sculling"],"group":"Endurance","q":{"maxStrength":3,"power":2,"rotational":0,"unilateral":1,"upperPull":3,"upperPush":1,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":2},"prehab":["lowback","hipAbd"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Sustained high-power aerobic efforts, about 6-8 minutes for a 2 km race.","summary":"Rowing is a powerful leg drive over a long aerobic effort. The plan builds heavy leg and pulling strength and back endurance, as leg strength is strongly linked to 2 km times and can be maintained with one or two heavy sessions a week in season.","evidence":[{"claim":"Lower-body strength and power (e.g. leg press) are moderately to strongly linked to 2,000 m ergometer times, and maximal strength can be maintained in season with one or two heavy sessions a week.","source":"Lawton, Cronin & McGuigan 2011, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworks2011/104"}],"confidence":"moderate"},{"id":"kayaking","name":"Kayaking / canoeing","aliases":["canoe","sprint kayak","paddling","sup"],"group":"Endurance","q":{"maxStrength":2,"power":2,"rotational":3,"unilateral":1,"upperPull":3,"upperPush":2,"lowerBody":1,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","lowback","wrist"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"upper","energy":"Aerobic paddling with sprint races lasting from about 30 seconds to 4 minutes.","summary":"Paddling depends on upper-body pulling strength and trunk rotation. The plan builds pulling and pressing strength with rotational trunk work and shoulder care; paddling-specific strength research is limited.","evidence":[],"confidence":"limited"},{"id":"trailrunning","name":"Trail / fell running","aliases":["fell running","mountain running","ultra","ultramarathon"],"group":"Endurance","q":{"maxStrength":2,"power":2,"rotational":0,"unilateral":3,"upperPull":0,"upperPush":0,"lowerBody":3,"grip":0,"neck":0,"trunk":2,"mass":0},"prehab":["ankle","calf","hipAbd","nordic"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Long aerobic efforts with steep climbs and descents over uneven ground.","summary":"Trail running is long aerobic running with hard climbs and technical descents. The plan uses strength and plyometric work, shown to improve running economy, plus ankle balance and calf work to cope with uneven ground.","evidence":[{"claim":"Strength training improves running economy, time-trial and sprint performance in middle- and long-distance runners without harming body composition; 2-3 sessions a week is recommended.","source":"Blagrove, Howatson & Hayes 2018, Sports Medicine","url":"https://repository.lboro.ac.uk/articles/journal_contribution/Effects_of_strength_training_on_the_physiological_determinants_of_middle-_and_long-distance_running_performance_a_systematic_review/9619553"},{"claim":"Strength training (resistance plus plyometrics, 2-3 times a week for 8-12 weeks) produced a large improvement in running economy in highly trained distance runners.","source":"Balsalobre-Fernández, Santos-Concejero & Grivas 2016, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/26694507/"},{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"}],"confidence":"moderate"},{"id":"xcski","name":"Cross-country skiing","aliases":["nordic skiing","xc skiing","skimo"],"group":"Endurance","q":{"maxStrength":3,"power":2,"rotational":1,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":3,"grip":1,"neck":0,"trunk":3,"mass":1},"prehab":["lowback","shoulderER"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"all","energy":"Long aerobic efforts with heavy upper-body involvement, especially in double poling.","summary":"Cross-country skiing uses the whole body over long aerobic efforts. The plan includes heavy upper-body pulling and leg strength, as heavy strength training has been shown to improve double-poling economy and endurance.","evidence":[{"claim":"Nine weeks of heavy upper-body strength training improved double-poling economy and time to exhaustion in cross-country skiers.","source":"Østerås, Helgerud & Hoff 2002, European Journal of Applied Physiology","url":"https://lida.sport-iat.de/ta/Record/4007707"},{"claim":"Adding heavy strength training to endurance training improves running and cycling economy and performance, with heavy strength work giving the clearest benefit for cyclists.","source":"Rønnestad & Mujika 2014, Scandinavian Journal of Medicine & Science in Sports","url":"https://doi.org/10.1111/sms.12104"}],"confidence":"moderate"},{"id":"climbing","name":"Rock climbing & bouldering","aliases":["bouldering","climbing","sport climbing"],"group":"Climbing & board","q":{"maxStrength":2,"power":2,"rotational":1,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":1,"grip":3,"neck":0,"trunk":3,"mass":0},"prehab":["fingers","shoulderER","wrist"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"upper","energy":"Repeated high-intensity grip efforts; short powerful moves in bouldering, longer sustained efforts on routes.","summary":"Climbing is limited by finger strength and pulling strength relative to body weight. The plan uses hangboard and pulling work, which improves finger strength, plus antagonist pushing and shoulder work to keep the joints balanced.","evidence":[{"claim":"Eight weeks of weighted hangboard training improved grip and finger strength in intermediate to advanced climbers compared with climbing alone.","source":"Mundry et al. 2021, Scientific Reports","url":"https://doi.org/10.1038/s41598-021-92898-2"}],"confidence":"moderate"},{"id":"skateboarding","name":"Skateboarding","aliases":["skate"],"group":"Climbing & board","q":{"maxStrength":1,"power":3,"rotational":2,"unilateral":3,"upperPull":0,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":2,"mass":1},"prehab":["ankle","landing","wrist"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":"lower","energy":"Short explosive efforts of jumping, pushing and landing.","summary":"Skateboarding is repeated jumping and hard landings. The plan builds leg power and single-leg strength with landing and ankle balance work, drawing on general jumping-sport research because skateboarding studies are scarce.","evidence":[{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"}],"confidence":"limited"},{"id":"alpineskiing","name":"Alpine skiing","aliases":["skiing","downhill skiing"],"group":"Snow & water","q":{"maxStrength":3,"power":2,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":3,"mass":2},"prehab":["landing","hipAbd","lowback"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated runs of 1-2 minutes with high, sustained leg loads, often eccentric.","summary":"Skiing puts high, sustained loads through the legs, especially when absorbing turns. The plan builds heavy leg strength and eccentric control with knee-protective landing work; skiing-specific trials are limited, so this draws on wider ACL research.","evidence":[{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"},{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"}],"confidence":"limited"},{"id":"snowboarding","name":"Snowboarding","aliases":["snowboard"],"group":"Snow & water","q":{"maxStrength":2,"power":2,"rotational":2,"unilateral":2,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":3,"mass":1},"prehab":["landing","wrist","ankle"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated runs with sustained squatting and occasional jumps and falls.","summary":"Snowboarding needs strong legs for sustained edging and good landing control. The plan builds leg strength, trunk stability and landing technique, plus wrist strength for falls; snowboard-specific research is limited.","evidence":[],"confidence":"limited"},{"id":"surfing","name":"Surfing","aliases":["surf","bodyboarding"],"group":"Snow & water","q":{"maxStrength":1,"power":2,"rotational":2,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":2,"grip":0,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","lowback"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":"upper","energy":"Long periods of paddling punctuated by explosive pop-ups and short rides.","summary":"Surfing is mostly paddling, with explosive pop-ups and short rides. The plan builds upper-body pulling endurance and trunk strength with shoulder care and leg power for the pop-up; surfing-specific strength research is limited.","evidence":[],"confidence":"limited"},{"id":"sailing","name":"Sailing","aliases":["dinghy sailing","yachting","windsurfing","kitesurfing"],"group":"Snow & water","q":{"maxStrength":2,"power":1,"rotational":1,"unilateral":1,"upperPull":3,"upperPush":1,"lowerBody":2,"grip":3,"neck":0,"trunk":3,"mass":1},"prehab":["lowback","shoulderER","wrist"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":null,"energy":"Long periods of sustained isometric holding (hiking) with bursts of pulling.","summary":"Dinghy sailing involves long isometric hiking holds and repeated rope pulling. The plan builds back, trunk and pulling endurance and grip strength; sailing-specific research is limited.","evidence":[],"confidence":"limited"},{"id":"sprinting","name":"Sprinting (track)","aliases":["sprint","100m","200m","400m","hurdles"],"group":"Athletics","q":{"maxStrength":3,"power":3,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":2,"mass":1},"prehab":["nordic","calf"],"season":{"off":3,"pre":3,"in":2},"avoidBefore":"lower","energy":"Maximal efforts of under a minute that rely on speed and power.","summary":"Sprinting is about producing large forces very quickly. The plan builds heavy leg strength and power, since squat strength gains carry over to sprint times, and includes Nordic hamstring work to protect against the commonest sprint injury.","evidence":[{"claim":"Gains in lower-body (squat) strength transfer to sprint performance, with strength gains strongly correlated with sprint improvements.","source":"Seitz et al. 2014, Sports Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/25059334/"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"strong"},{"id":"jumps","name":"Jumping events","aliases":["long jump","triple jump","high jump","pole vault"],"group":"Athletics","q":{"maxStrength":3,"power":3,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":2,"mass":1},"prehab":["landing","calf","nordic"],"season":{"off":3,"pre":3,"in":2},"avoidBefore":"lower","energy":"Maximal single explosive efforts with full recovery between attempts.","summary":"Jumping events depend on explosive leg power and stiff, strong tendons. The plan uses heavy strength and power work for the legs with calf and landing work; event-specific trials are limited, so this draws on wider strength and sprint research.","evidence":[{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"},{"claim":"Gains in lower-body (squat) strength transfer to sprint performance, with strength gains strongly correlated with sprint improvements.","source":"Seitz et al. 2014, Sports Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/25059334/"}],"confidence":"limited"},{"id":"throws","name":"Throwing events","aliases":["shot put","discus","javelin","hammer"],"group":"Athletics","q":{"maxStrength":3,"power":3,"rotational":3,"unilateral":2,"upperPull":2,"upperPush":3,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":2},"prehab":["shoulderER","lowback"],"season":{"off":3,"pre":3,"in":2},"avoidBefore":"all","energy":"Single maximal explosive efforts with full recovery between attempts.","summary":"Throwing events need maximal strength and rotational power, and extra muscle mass helps. The plan prioritises heavy lifting and power with shoulder care, based on strength research as throws-specific trials are limited.","evidence":[{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"}],"confidence":"limited"},{"id":"golf","name":"Golf","aliases":[],"group":"Other","q":{"maxStrength":1,"power":2,"rotational":3,"unilateral":2,"upperPull":1,"upperPush":1,"lowerBody":2,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["lowback","shoulderER","wrist","hipAbd"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":null,"energy":"Low physical intensity overall with repeated maximal swings over several hours of walking.","summary":"Golf is a series of fast, rotational swings over a long walk. The plan builds leg and trunk power and grip strength, which are linked to clubhead speed and driving distance, plus back and shoulder care.","evidence":[{"claim":"Driving distance and clubhead speed relate to muscle strength, with leg-hip power, trunk power and grip strength most relevant; combined strength programmes often improve swing speed.","source":"Torres-Ronda, Sánchez-Medina & González-Badillo 2011, Journal of Sports Science and Medicine","url":"https://www.jssm.org/jssm-10-9.xml-Fulltext"}],"confidence":"moderate"},{"id":"gymnastics","name":"Gymnastics","aliases":["artistic gymnastics","calisthenics","trampolining"],"group":"Other","q":{"maxStrength":3,"power":3,"rotational":1,"unilateral":2,"upperPull":3,"upperPush":3,"lowerBody":3,"grip":3,"neck":0,"trunk":3,"mass":0},"prehab":["wrist","landing","shoulderER","lowback"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Short, maximal efforts of strength, power and control lasting seconds to about 90 seconds.","summary":"Gymnastics demands high strength relative to body weight, explosive power and resilient wrists and shoulders. The plan focuses on relative strength, landing control and wrist and shoulder care; gym-based research in gymnasts is limited.","evidence":[],"confidence":"limited"},{"id":"dance","name":"Dance","aliases":["ballet","contemporary dance"],"group":"Other","q":{"maxStrength":1,"power":2,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":2,"grip":0,"neck":0,"trunk":2,"mass":0},"prehab":["ankle","calf","landing","hipAbd"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":"lower","energy":"Intermittent bursts of jumping and movement during long rehearsals and performances.","summary":"Dance needs strong, controlled legs and ankles for jumps and landings without adding bulk. The plan focuses on single-leg strength, calf and ankle work and landing control; dance-specific strength research is limited.","evidence":[{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"}],"confidence":"limited"},{"id":"horseriding","name":"Horse riding","aliases":["equestrian","eventing","show jumping","dressage","jockey"],"group":"Other","q":{"maxStrength":1,"power":1,"rotational":1,"unilateral":1,"upperPull":1,"upperPush":1,"lowerBody":2,"grip":1,"neck":0,"trunk":3,"mass":0},"prehab":["lowback","hipAbd"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":null,"energy":"Sustained postural work with moderate aerobic demands, higher in eventing and racing.","summary":"Riding relies on trunk control, leg strength and back endurance to stay balanced in the saddle. The plan focuses on trunk, back and hip strength; riding-specific strength research is limited.","evidence":[],"confidence":"limited"}]};
